from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class RangeCompression(Strategy):
    rationale = (
        "Range compression indicates a potential for increased volatility and price movement. "
        "By identifying symbols with reduced range between high and low over a period, we can "
        "anticipate that these stocks might experience significant price action."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window * len(view.symbols):
            return Signal(information_available_at=stamp, weights={})

        picks: list[str] = []
        for symbol in view.symbols:
            df = history.select(
                pl.col("symbol"), pl.col("session_date"), pl.col("high"), pl.col("low")
            ).filter(pl.col("symbol") == symbol)
            if df.is_empty():
                continue
            high_values = [float(v) for v in df["high"].to_list()]
            low_values = [float(v) for v in df["low"].to_list()]
            range_value = max(high_values) - min(low_values)
            if range_value <= 0.1 * (max(high_values) - min(high_values)).mean():
                picks.append(symbol)

        picks = picks[:5]  # Select top 5 symbols
        if not picks:
            return Signal(information_available_at=stamp, weights={})
        weight = 1.0 / len(picks)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in picks}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
